SELECT (SELECT illrequestattributes.value FROM illrequestattributes LEFT JOIN illrequests ON illrequestattributes.illrequest_id=illrequests.illrequest_id LEFT JOIN items ON items.biblionumber=illrequests.biblio_id WHERE illrequestattributes.type="itemAgencyCode" AND items.barcode=<<item barcode>> GROUP BY illrequests.illrequest_id) AS "itemAgencyCode", (SELECT illrequestattributes.value FROM illrequestattributes LEFT JOIN illrequests ON illrequestattributes.illrequest_id=illrequests.illrequest_id LEFT JOIN items ON items.biblionumber=illrequests.biblio_id WHERE illrequestattributes.type="patronAgencyCode" AND items.barcode=<<item barcode>> GROUP BY illrequests.illrequest_id) AS "patronAgencyCode",  (SELECT illrequestattributes.value FROM illrequestattributes LEFT JOIN illrequests ON illrequestattributes.illrequest_id=illrequests.illrequest_id LEFT JOIN items ON items.biblionumber=illrequests.biblio_id WHERE illrequestattributes.type="centralPatronType" AND items.barcode=<<item barcode>> GROUP BY illrequests.illrequest_id) AS "centralPatronType",(SELECT illrequestattributes.value FROM illrequestattributes LEFT JOIN illrequests ON illrequestattributes.illrequest_id=illrequests.illrequest_id LEFT JOIN items ON items.biblionumber=illrequests.biblio_id WHERE illrequestattributes.type="patronName" AND items.barcode=<<item barcode>> GROUP BY illrequests.illrequest_id) AS "patronName", (SELECT illrequestattributes.value FROM illrequestattributes LEFT JOIN illrequests ON illrequestattributes.illrequest_id=illrequests.illrequest_id LEFT JOIN items ON items.biblionumber=illrequests.biblio_id WHERE illrequestattributes.type="pickupLocation" AND items.barcode=<<item barcode>> GROUP BY illrequests.illrequest_id) AS "pickupLocation", i.homebranch, r.borrowernumber, r.illrequest_id, i.itemnumber, i.itype, i.itemcallnumber, o.author, o.title, o.subtitle, i.barcode, b.cardnumber, b.surname, i.enumchron
FROM illrequests r
LEFT JOIN illrequestattributes a ON r.illrequest_id=a.illrequest_id
LEFT JOIN items i ON i.biblionumber=r.biblio_id
LEFT JOIN borrowers b ON r.borrowernumber=b.borrowernumber
LEFT JOIN biblio o ON i.biblionumber=o.biblionumber
WHERE i.barcode=<<item barcode>>
GROUP BY r.illrequest_id